package kosanku.model;

public class Tenants {
    private int id;
    private String idNumber;      // NIK / KTP, column id_number
    private String name;
    private String email;         // optional, may be null
    private String phoneNumber;
    private boolean visible;       // column is_visible (false = soft-deleted)

    // Matches the database default (is_visible = TRUE)
    public Tenants() {
        this.visible = true;
    }

    // For inserting a new tenant (id is generated by the database)
    public Tenants(String idNumber, String name, String email, String phoneNumber) {
        this.idNumber = idNumber;
        this.name = name;
        this.email = email;
        this.phoneNumber = phoneNumber;
        this.visible = true;
    }
    
    // Full constructor (for reading from the database)
    public Tenants(int id, String idNumber, String name, String email, String phoneNumber, boolean visible) {
        this.id = id;
        this.idNumber = idNumber;
        this.name = name;
        this.email = email;
        this.phoneNumber = phoneNumber;
        this.visible = visible;
    }

    public int getId() {return id;}
    public String getIdNumber() {return idNumber;}
    public String getName() {return name;}
    public String getEmail() {return email;}
    public String getPhoneNumber() {return phoneNumber;}
    public boolean isvisible() {return visible;}

    public void setId(int id) {this.id = id;}
    public void setIdNumber(String idNumber) {this.idNumber = idNumber;}
    public void setName(String name) {this.name = name;}
    public void setEmail(String email) {this.email = email;}
    public void setPhoneNumber(String phoneNumber) {this.phoneNumber = phoneNumber;}
    public void setvisible(boolean visible) {this.visible = visible;}

    @Override
    public String toString() {
        return name;
    }
}
